#!/usr/bin/env node
/**
 * Writes public/sitemap.xml from the city slug catalog, limited to
 * SUPPORTED_COUNTRIES_PROD (production SEO surface).
 *
 * Run: yarn generate-sitemap
 * Also runs automatically via prebuild.
 *
 * Do not edit public/sitemap.xml by hand.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { getSeoCitySlugs } from '../src/config/citySlugCatalog.js';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const CONSTANTS_PATH = path.join(ROOT, 'src/config/constants.js');
const OUT_PATH = path.join(ROOT, 'public/sitemap.xml');
const SITE_ORIGIN = 'https://ciclomapa.app';

/**
 * Read PROD country codes from constants.js without importing it (that module
 * touches `window` at load time).
 * @returns {string[]}
 */
function readProdCountryCodes() {
  const source = fs.readFileSync(CONSTANTS_PATH, 'utf8');
  const match = source.match(
    /export const SUPPORTED_COUNTRIES_PROD\s*=\s*Object\.freeze\(\[([\s\S]*?)\]\)/
  );
  if (!match) {
    throw new Error('Could not find SUPPORTED_COUNTRIES_PROD in constants.js');
  }
  const codes = [...match[1].matchAll(/code:\s*'([a-z]{2})'/g)].map((m) => m[1]);
  if (codes.length === 0) {
    throw new Error('SUPPORTED_COUNTRIES_PROD has no country codes');
  }
  return codes;
}

function escapeXml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function urlEntry(loc, { changefreq, priority }) {
  return [
    '  <url>',
    `    <loc>${escapeXml(loc)}</loc>`,
    `    <changefreq>${changefreq}</changefreq>`,
    `    <priority>${priority}</priority>`,
    '  </url>',
  ].join('\n');
}

function buildSitemapXml(citySlugs) {
  const entries = [
    urlEntry(`${SITE_ORIGIN}/`, { changefreq: 'weekly', priority: '1.0' }),
    ...citySlugs.map((slug) =>
      urlEntry(`${SITE_ORIGIN}/${slug}`, { changefreq: 'weekly', priority: '0.8' })
    ),
    urlEntry(`${SITE_ORIGIN}/privacidade`, { changefreq: 'yearly', priority: '0.3' }),
  ];

  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<!-- Generated by scripts/generate-sitemap.mjs — do not edit by hand. -->',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    ...entries,
    '</urlset>',
    '',
  ].join('\n');
}

function main() {
  const countryCodes = readProdCountryCodes();
  const citySlugs = getSeoCitySlugs(countryCodes);
  if (citySlugs.length === 0) {
    throw new Error(
      `No SEO city slugs for countries: ${countryCodes.join(', ')}. Check catalog countrycodes.`
    );
  }

  const xml = buildSitemapXml(citySlugs);
  fs.writeFileSync(OUT_PATH, xml, 'utf8');
  console.log(
    `Wrote ${path.relative(ROOT, OUT_PATH)} with ${citySlugs.length} city URLs ` +
      `(countries: ${countryCodes.join(', ')})`
  );
}

main();
